다음 JAVA 코드를 실행한 결과 중, 가장 적절한 것은?

import java.util.ArrayList; import java.util.Collection; import java.util.HashMap; import java.util.HashSet; import java.util.LinkedList; import java.util.List; import java.util.Map; import java.util.Set; import java.util.Stack; import java.util.TreeMap; import java.util.TreeSet;
public class TestB
{
public static int list = 0, map = 0, set = 0,
collection = 0;
public static void collectionCounter(Object abc)
{
if (abc instanceof List) list++; if (abc instanceof Map) map++; if (abc instanceof Set) set++; if (abc instanceof Collection) collection++;
}
public static void main(String[] args)
{
collectionCounter(new HashSet<Object>()); collectionCounter(new HashMap<Object, Object>()); collectionCounter(new ArrayList<Object>()); collectionCounter(new LinkedList<Object>()); collectionCounter(new Stack<Object>()); collectionCounter(new TreeSet<Object>()); collectionCounter(new TreeMap<Object, Object>()); System.out.println("list = "+list+" map = "+map+" set = "+set+" collection = "+collection);
}
}

